const stats = $input.first().json;
const { month, orders, top_products, web_interactions } = stats;

const revenue = orders.revenue ? orders.revenue.toLocaleString('es-AR', { style: 'currency', currency: 'ARS' }) : '$0';
const interactions = web_interactions.reduce((acc, i) => { acc[i.tipo] = i.count; return acc; }, {});

const topProductsHtml = (top_products || []).map(p =>
  `<tr><td>${p.nombre}</td><td>${p.sku}</td><td>${p.units_sold}</td></tr>`
).join('');

const html = `<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"><title>Reporte Mensual Golden Harvest — ${month}</title>
<style>body{font-family:Arial,sans-serif;max-width:700px;margin:0 auto;padding:20px;color:#333}
h1{color:#8B6914}table{width:100%;border-collapse:collapse;margin:16px 0}
th,td{border:1px solid #ddd;padding:8px;text-align:left}th{background:#f5f0e8}</style></head>
<body>
<h1>📊 Reporte Mensual — ${month}</h1>
<h2>Resumen de Pedidos</h2>
<table><tr><th>Métrica</th><th>Valor</th></tr>
<tr><td>Pedidos totales</td><td>${orders.total_orders || 0}</td></tr>
<tr><td>Clientes únicos</td><td>${orders.unique_customers || 0}</td></tr>
<tr><td>Facturación</td><td>${revenue}</td></tr>
</table>
<h2>Productos más vendidos</h2>
<table><tr><th>Producto</th><th>SKU</th><th>Unidades</th></tr>${topProductsHtml}</table>
<h2>Interacciones Web</h2>
<table><tr><th>Tipo</th><th>Cantidad</th></tr>
${Object.entries(interactions).map(([k,v]) => `<tr><td>${k}</td><td>${v}</td></tr>`).join('')}
</table>
<p style="color:#888;font-size:12px">Generado automáticamente por n8n — Golden Harvest S.A.</p>
</body></html>`;

return [{ json: { month, html_report: html, summary: { revenue, total_orders: orders.total_orders, unique_customers: orders.unique_customers } } }];
